13.3 Python-skript for JWT-batch-analyse

import base64, json, sys, time

def decode_jwt(token):
    parts = token.split('.')
    if len(parts) != 3:
        return None
    payload = parts[1] + '==' * (4 - len(parts[1]) % 4)
    try:
        data = json.loads(base64.urlsafe_b64decode(payload))
        exp = data.get('exp', 0)
        data['_expired'] = exp < time.time() if exp else 'ukjent'
        return data
    except:
        return None

# Les tokens fra fil (en per linje):
with open('tokens.txt') as f:
    for line in f:
        token = line.strip()
        if token.startswith('eyJ'):
            result = decode_jwt(token)
            if result:
                print(json.dumps(result, indent=2))
